import * as React from "react";
import "./ModalTitle.scss";
import { IconButton } from "../../iconButton";
import clsx from "clsx";

interface ModalTitleProps {
  id: string;
  title?: string;
  thumbnail?: React.ReactNode;
  onClose?: () => void;
  showClose?: boolean;
}

const ModalTitle = ({
  id,
  title,
  thumbnail,
  onClose,
  showClose,
}: ModalTitleProps) => {
  return (
    <div className="modal-title-container">
      <div
        className={clsx("modal-title", { "modal-with-thumbnail": thumbnail })}
      >
        {title && !thumbnail && <h4 className="modal-header">{title}</h4>}
        {showClose && (
          <div className="modal-close">
            <IconButton
              id={`${id}-close-btn`}
              className="close-icon-button"
              icon="Cross_SGDS"
              btnType="standard"
              size="large"
              colour="onSurface"
              onClick={onClose}
            />
          </div>
        )}
      </div>
      {thumbnail && <div className="modal-thumbnail">{thumbnail}</div>}
    </div>
  );
};

export default ModalTitle;
